self.onInit = function () {
    var SHOW_ACK = true;        // acknowledge button
    var REFRESH_MS = 30000;     // automatic refresh
    var MAX_PAGES = 5;          // 5 x 100 alarms at most
    
        // styles of the dynamically created elements (the template CSS does not reach them)
    var styleEl = document.createElement('style');
    styleEl.textContent =
        '.ar-wrap .ar-dev { margin-top: 18px; }' +
        '.ar-wrap .ar-dev:first-child { margin-top: 0; }' +
        '.ar-wrap .ar-dev-name { font-size: 14px; font-weight: 700; }' +
        '.ar-wrap .ar-row { display: flex; align-items: center; gap: 8px; padding: 3px 0 3px 8px; font-size: 13px; }' +
        '.ar-wrap .ar-dot { flex: 0 0 auto; width: 10px; height: 10px; border-radius: 50%; }' +
        '.ar-wrap .ar-type { flex: 1; min-width: 0; }' +
        '.ar-wrap .ar-meta { flex: 0 0 auto; font-size: 11px; opacity: 0.8; text-align: right; }' +
        '.ar-wrap .ar-ack { flex: 0 0 auto; padding: 2px 8px; border: none; border-radius: 8px; ' +
            'background: #6E9FCB; color: #000000; font-size: 11px; font-weight: 600; cursor: pointer; }' +
        '.ar-wrap .ar-empty { font-size: 13px; padding-left: 8px; }' +
        '.ar-wrap .ar-err { font-weight: 600; font-size: 13px; }';
    document.head.appendChild(styleEl);
    self.ctx.arStyle = styleEl;

    var root = self.ctx.$container[0];
    var $ = function (s) { return root.querySelector(s); };
    var http = self.ctx.http;
    var list = $('.ar-list');
    var statusSel = $('.ar-status');
    var filter = $('.ar-filter');
    var refreshBtn = $('.ar-refresh');
    var alarms = [];
    var timer = null;

    var SEV = {
        CRITICAL:      { rank: 0, color: '#c0392b', name: 'Kritikus' },
        MAJOR:         { rank: 1, color: '#e67e22', name: 'Súlyos' },
        MINOR:         { rank: 2, color: '#f1c40f', name: 'Kisebb' },
        WARNING:       { rank: 3, color: '#3498db', name: 'Figyelmeztetés' },
        INDETERMINATE: { rank: 4, color: '#95a5a6', name: 'Meghatározatlan' }
    };

    var STATUS = {
        ACTIVE_UNACK:  'Aktív',
        ACTIVE_ACK:    'Aktív, nyugtázva',
        CLEARED_UNACK: 'Megszűnt',
        CLEARED_ACK:   'Megszűnt, nyugtázva'
    };

    function errText(e) {
        if (!e) { return 'Ismeretlen hiba'; }
        var m = (e.error && e.error.message) ? e.error.message : '';
        return (e.status ? e.status + ' ' : '') + (e.url ? '[' + e.url + '] ' : '') + (m || 'Ismeretlen hiba');
    }

    function el(tag, cls, text) {
        var e = document.createElement(tag);
        if (cls) { e.className = cls; }
        if (text) { e.textContent = text; }
        return e;
    }

    function deviceName(a) {
        return a.originatorName || a.originatorLabel || (a.originator && a.originator.id) || '?';
    }

    function render() {
        var q = filter.value.trim().toLowerCase();
        list.textContent = '';

        // group by device
        var groups = {};
        alarms.forEach(function (a) {
            var n = deviceName(a);
            if (q && n.toLowerCase().indexOf(q) < 0) { return; }
            (groups[n] = groups[n] || []).push(a);
        });
        var names = Object.keys(groups).sort(function (x, y) { return x.localeCompare(y); });

        if (!names.length) { list.appendChild(el('div', 'ar-empty', 'Nincs riasztás.')); return; }

        names.forEach(function (n) {
            var items = groups[n].sort(function (x, y) {
                var rx = (SEV[x.severity] || SEV.INDETERMINATE).rank;
                var ry = (SEV[y.severity] || SEV.INDETERMINATE).rank;
                return rx - ry || (y.startTs || 0) - (x.startTs || 0);
            });

            var block = el('div', 'ar-dev');
            block.appendChild(el('div', 'ar-dev-name', n + ' (' + items.length + ')'));

            items.forEach(function (a) {
                var sev = SEV[a.severity] || SEV.INDETERMINATE;
                var row = el('div', 'ar-row');

                var dot = el('span', 'ar-dot');
                dot.style.background = sev.color;
                dot.title = sev.name;
                row.appendChild(dot);

                row.appendChild(el('span', 'ar-type', String(a.type).replace(/^AUTO\s+/, '')));

                var when = new Date(a.startTs || a.createdTime).toLocaleString('hu-HU');
                row.appendChild(el('span', 'ar-meta', (STATUS[a.status] || a.status) + ' · ' + when));

                if (SHOW_ACK && String(a.status).indexOf('UNACK') > 0) {
                    var b = el('button', 'ar-ack', 'Nyugtáz');
                    b.addEventListener('click', function () {
                        b.disabled = true;
                        http.post('/api/alarm/' + a.id.id + '/ack', {}).subscribe(
                            function () { load(); },
                            function (e) { b.disabled = false; alert('Hiba: ' + errText(e)); }
                        );
                    });
                    row.appendChild(b);
                }
                block.appendChild(row);
            });
            list.appendChild(block);
        });
    }

    function load() {
        var items = [];
        (function next(page) {
            http.get('/api/alarms?searchStatus=' + statusSel.value + '&pageSize=100&page=' + page +
                     '&sortProperty=createdTime&sortOrder=DESC&fetchOriginator=true').subscribe(
                function (res) {
                    items = items.concat(res.data || []);
                    if (res.hasNext && page + 1 < MAX_PAGES) { next(page + 1); }
                    else { alarms = items; render(); }
                },
                function (e) {
                    list.textContent = '';
                    list.appendChild(el('div', 'ar-err', 'Hiba: ' + errText(e)));
                }
            );
        })(0);
    }

    refreshBtn.addEventListener('click', load);
    statusSel.addEventListener('change', load);
    filter.addEventListener('input', render);

    load();
    timer = setInterval(load, REFRESH_MS);
    self.ctx.arTimer = timer;
};

self.onDestroy = function () {
    if (self.ctx.arTimer) { clearInterval(self.ctx.arTimer); }
    if (self.ctx.arStyle && self.ctx.arStyle.parentNode) { self.ctx.arStyle.parentNode.removeChild(self.ctx.arStyle); }
};

